def normalizar(t):
    return re.sub(r"[^\wáéíóúñü ]", "", t.lower()).split()

def shingles(t, k=3):
    w = normalizar(t)
    return {" ".join(w[i:i + k]) for i in range(len(w) - k + 1)}

